/**
 * Skill emission: `skillToTf` consumes the discovered `DeployableEntity`
 * (the `skill` def() payload) and emits `elementum_agentic_skill` +
 * one tool resource per implemented tool (the tool pass delegates to
 * `entities/skill-tool/to-tf.ts`). Mirrors `entities/agent/to-tf.ts`.
 *
 * The dialect is the live provider's ACTUAL schema (confirmed against the
 * deployed `elementum` provider, `main` branch of the ei terraform provider
 * repo — not `pristine-refactor`'s older, generic single-tool-resource
 * shape): `owner_id`/`owner_type` as the owning app's resource ref +
 * `"APP_ASPECT"`, `name`/`description`/`instructions`/`status`/`type`/
 * `properties`, plus typed discovery/routing fields. Access policy
 * (user_ids/group_ids) is not authored yet.
 */
import { EntityTfError } from "../../engine/entity.js";
import { appScopedResourceLabel, expr, sanitizeName, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { skillToolToTf } from "../skill-tool/to-tf.js";
import { APP_RESOURCE_TYPE } from "../app/module.js";
import { SERVICE_ACCOUNT_RESOURCE_TYPE } from "../service-account/module.js";
import { analyzeSkillInputCoverage, coverageToolsFromWire, skillCoverageGapDiagnostics, skillCoverageReportLines, } from "./input-coverage.js";
import { SKILL_RESOURCE_TYPE } from "./module.js";
function serviceAccountValue(name, ctx) {
    const matches = Object.entries(ctx.serviceAccounts ?? {}).filter(([, account]) => `${account.firstName} ${account.lastName}`.trim() === name);
    if (matches.length > 1) {
        throw new EntityTfError(`service account name ${JSON.stringify(name)} is ambiguous in app ${JSON.stringify(ctx.appRefName)}`);
    }
    const local = matches[0];
    if (local !== undefined) {
        return expr.resourceAttr(SERVICE_ACCOUNT_RESOURCE_TYPE, appScopedResourceLabel(ctx.appTfLabel, tsLabelToTfLabel(local[0])), ["id"]);
    }
    const label = appScopedResourceLabel(ctx.appTfLabel, sanitizeName(name));
    ctx.orgRefs.rawLookup(SERVICE_ACCOUNT_RESOURCE_TYPE, label, name, {
        app_id: expr.resourceAttr(APP_RESOURCE_TYPE, ctx.appTfLabel, ["id"]),
    });
    return expr.dataAttr(SERVICE_ACCOUNT_RESOURCE_TYPE, label, ["id"]);
}
function toSortableSkills(entities) {
    const out = [];
    for (const entity of entities) {
        if (entity.kind !== "skill")
            continue;
        const payload = entity.payload;
        out.push({ refName: entity.refName, tools: payload?.tools ?? [] });
    }
    return out;
}
/** Return deterministic suffixes for duplicate tool names within one skill. */
export function computeToolLabelSuffixes(siblingSkills) {
    const counts = new Map();
    const suffixes = new Map();
    for (const skill of toSortableSkills(siblingSkills)) {
        skill.tools.forEach((entry, index) => {
            const typeKey = Object.keys(entry)[0];
            if (typeKey === undefined)
                return;
            const inner = entry[typeKey];
            const base = sanitizeName(inner?.name ?? "");
            const key = `${skill.refName}\0${base}`;
            const count = counts.get(key) ?? 0;
            counts.set(key, count + 1);
            suffixes.set(`${skill.refName}#${index}`, count > 0 ? `_${count}` : "");
        });
    }
    return suffixes;
}
/** `elementum_agentic_skill` + one tool resource per implemented tool, in the platform's dialect. */
export function skillToTf(entity, ctx) {
    if (entity.kind !== "skill") {
        throw new EntityTfError(`skillToTf expects kind "skill"; got "${entity.kind}" (refName "${entity.refName}")`);
    }
    const payload = entity.payload;
    const elementum = payload?.skill;
    if (payload === null || typeof payload !== "object" || elementum === undefined) {
        throw new EntityTfError(`skill "${entity.refName}" has no skill payload — was it built with skill?`);
    }
    const skillBareTfLabel = tsLabelToTfLabel(entity.refName);
    const tfLabel = appScopedResourceLabel(ctx.appTfLabel, skillBareTfLabel);
    const name = elementum.name ?? "";
    const coverage = analyzeSkillInputCoverage(name, elementum.instructions ?? "", coverageToolsFromWire(payload.tools ?? []));
    ctx.reports?.push(...skillCoverageReportLines(coverage));
    ctx.diagnostics.push(...skillCoverageGapDiagnostics(coverage));
    const attrs = {
        owner_id: expr.resourceAttr(APP_RESOURCE_TYPE, ctx.appTfLabel, ["id"]),
        owner_type: "APP_ASPECT",
        name,
        description: elementum.description ?? "",
        instructions: elementum.instructions ?? "",
        status: elementum.status ?? "DRAFT",
        type: elementum.type ?? "CUSTOM",
    };
    if (elementum.properties !== undefined) {
        attrs["properties"] = JSON.stringify(elementum.properties);
    }
    const discovery = elementum.discovery;
    if (discovery?.routingPriority !== undefined)
        attrs["routing_priority"] = discovery.routingPriority;
    if (discovery?.aliases !== undefined)
        attrs["aliases"] = [...discovery.aliases];
    if (discovery?.exampleUtterances !== undefined)
        attrs["example_utterances"] = [...discovery.exampleUtterances];
    if (discovery?.positiveKeywords !== undefined)
        attrs["positive_keywords"] = [...discovery.positiveKeywords];
    if (discovery?.negativeKeywords !== undefined)
        attrs["negative_keywords"] = [...discovery.negativeKeywords];
    const toolLabelSuffixes = computeToolLabelSuffixes(ctx.siblingEntities ?? [entity]);
    const blocks = [{ kind: "resource", type: SKILL_RESOURCE_TYPE, label: tfLabel, attrs }];
    (payload.tools ?? []).forEach((entry, index) => {
        const tool = skillToolToTf(entry, {
            appRefName: ctx.appRefName,
            appTfLabel: ctx.appTfLabel,
            skillTfLabel: tfLabel,
            skillBareTfLabel,
            labelSuffix: toolLabelSuffixes.get(`${entity.refName}#${index}`) ?? "",
            ...(ctx.activeAutomationRefNames !== undefined && { activeAutomationRefNames: ctx.activeAutomationRefNames }),
            foreignAppRef: (l, n, ns) => ctx.orgRefs.foreignApp(l, n, ns),
            foreignElementRef: (l, n, ns) => ctx.orgRefs.foreignElement(l, n, ns),
            foreignFieldRef: (t, l, o, n) => ctx.orgRefs.foreignField(t, l, o, n),
            workspaceAspects: ctx.workspaceAspects,
            serviceAccountRef: (_label, serviceAccountName) => serviceAccountValue(serviceAccountName, ctx),
            diagnostics: ctx.diagnostics,
        });
        if (tool !== undefined)
            blocks.push(tool.block);
    });
    return { blocks, address: `${SKILL_RESOURCE_TYPE}.${tfLabel}` };
}
